try:
    ds = load_dataset("Open-Orca/OpenOrca", split="train")
    count = 0
    for item in ds:
        if item.get("question") and item.get("response"):
            examples.append({
                "instruction": item["question"],
                "response": item["response"][:500],
                "category": "reasoning"
            })
            count += 1
            if count >= 2000:
                break
    print(f"   Added {count:,} examples\n")
except Exception as e:
    print(f"   Error: {str(e)[:80]}\n")

# 3. OpenMathInstruct (7.3M)
print("3. OpenMathInstruct-1 (7.3M)...")
try:
    ds = load_dataset("nvidia/OpenMathInstruct-1", split="train")
    count = 0
    for item in ds:
        if item.get("instruction") and item.get("response"):
            examples.append({
                "instruction": item["instruction"][:300],
                "response": item["response"][:500],
                "category": "code"
            })
            count += 1
            if count >= 2000:
                break
    print(f"   Added {count:,} examples\n")
except Exception as e:
    print(f"   Error: {str(e)[:80]}\n")

# 4. NuminaMath (859K)
print("4. NuminaMath-CoT (859K)...")
try:
    ds = load_dataset("AI-MO/NuminaMath-CoT", split="train")
    count = 0
    for item in ds:
        if item.get("problem") and item.get("solution"):
            examples.append({
                "instruction": item["problem"][:300],
                "response": item["solution"][:500],
                "category": "reasoning"
            })
            count += 1
            if count >= 1000:
                break
    print(f"   Added {count:,} examples\n")
except Exception as e:
    print(f"   Error: {str(e)[:80]}\n")

# 5. SQuAD (87K)
print("5. rajpurkar/squad (87K)...")
try:
    ds = load_dataset("rajpurkar/squad", split="train")
    count = 0
    for item in ds:
        if item.get("question") and item.get("answers"):
            answers = item["answers"]
            if answers.get("text") and answers["text"]:
                examples.append({
                    "instruction": item["question"],
                    "response": answers["text"][0][:500],
                    "category": "chat"
                })
                count += 1
                if count >= 1000:
                    break
    print(f"   Added {count:,} examples\n")
except Exception as e:
    print(f"   Error: {str(e)[:80]}\n")

# EXISTING DATA (8,103)
print("[EXISTING] ORIGINAL DATASETS\n")

print("6. Existing formatted data...")
try:
    existing_file = SAVE_DIR / "training_data_formatted.jsonl"
    if existing_file.exists():
        count = 0
        with open(existing_file) as f:
            for line in f:
                try:
                    item = json.loads(line)
                    examples.append(item)
                    count += 1
                except:
                    pass
        print(f"   Added {count:,} examples\n")
    else:
        print("   File not found\n")
except Exception as e:
    print(f"   Error: {str(e)[:80]}\n")

# SAVE MEGA FILE
print("=" * 70)
print(f"SAVING {len(examples):,} TOTAL EXAMPLES")
print("=" * 70)

with open(OUTPUT_FILE, "w") as f:
    for example in examples:
        f.write(json.dumps(example) + "\n")

# Stats
chat_count = sum(1 for e in examples if e.get("category") == "chat")
code_count = sum(1 for e in examples if e.get("category") == "code")
reasoning_count = sum(1 for e in examples if e.get("category") == "reasoning")

print(f"\nTotal examples: {len(examples):,}")
print(f"  Chat:      {chat_count:>8,}")
print(f"  Code:      {code_count:>8,}")
print(f"  Reasoning: {reasoning_count:>8,}")
print(f"\nOutput file: {OUTPUT_FILE}")
print(f"File size: {OUTPUT_FILE.stat().st_size / 1024 / 1024:.1f} MB")
print("\n[READY] Use this file to fine-tune Qwen into Claude-like local LLM!")
"
  }
}
